using Dapper; using MySql.Data.MySqlClient; using ProviderMicroService.Domain; namespace ProviderMicroService.Infrastructure; public class ProviderRepository:IProviderRepository{ string cs; public ProviderRepository(string c)=>cs=c; MySqlConnection Conn()=>new(cs); public async Task<IEnumerable<Provider>> ListAsync(){using var c=Conn();await c.OpenAsync();return await c.QueryAsync<Provider>("SELECT * FROM providers WHERE is_deleted=0");} public async Task<Provider?> GetAsync(int id){using var c=Conn();await c.OpenAsync();return await c.QuerySingleOrDefaultAsync<Provider>("SELECT * FROM providers WHERE id=@id",new{id});} public async Task<Provider> CreateAsync(Provider p){using var c=Conn();await c.OpenAsync();p.Id=await c.ExecuteScalarAsync<int>("INSERT INTO providers(first_name,last_name,email,phone) VALUES(@FirstName,@LastName,@Email,@Phone); SELECT LAST_INSERT_ID();",p);return p;} public async Task<Provider> UpdateAsync(Provider p){using var c=Conn();await c.OpenAsync();await c.ExecuteAsync("UPDATE providers SET first_name=@FirstName,last_name=@LastName,email=@Email,phone=@Phone WHERE id=@Id",p);return p;} public async Task<bool> DeleteAsync(int id){using var c=Conn();await c.OpenAsync();await c.ExecuteAsync("UPDATE providers SET is_deleted=1 WHERE id=@id",new{id});return True;} }